mapper.select:
select * from ( SELECT distinct m.iot_device_id, od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.device_status, (CASE WHEN m.device_status = '0' THEN '在线' WHEN m.device_status = '1' THEN '离线' WHEN m.device_status = '2' THEN '从未连接' END) deviceStatusName, m.category_code, od.ord_status as orderStatus, m.longitude, m.latitude, m.location, m.height, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'radar_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, m.device_model_code, m.w_zone, m.device_period, m.par_angle, od.tenant_id as tenantId, pro.area_name as provinceName, pro.area_code as province_id, city.area_name as cityName, city.area_code as city_id, county.area_name as countyName, county.area_code as county_id, town.area_code as town_code, town.area_name as town_name,
case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
st.tenant_name as tenantName FROM vm_order_sensor_devices od LEFT JOIN vm_order_customer oc on od.order_code = oc.order_code LEFT JOIN vm_iot_device_t m on m.device_code = od.device_code and m.category_code = 1 LEFT JOIN sys_tenant_info st on st.tenant_id = od.tenant_id LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.delete_flag='0' and ten.industry_code = od.industry_code
left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '8' AND dct.user_id = #{param.userId}
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = m.device_code and vod.delete_flag = '0' and vod.tenant_id = od.tenant_id where od.delete_flag = '0' and m.delete_flag = '0' and od.category_code = 1 and od.tenant_id =#{param.tenantId}
and vod.dept_id in
#{id}
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_status = #{param.deviceStatus}
and m.model_code = #{param.modelCode}
and m.device_type in
#{deviceType}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
${param.dataScope} GROUP BY od.tenant_id, od.industry_code, od.device_code
order by od.device_code
order by device_name
order by m.device_status
order by m.model_code
order by vod.dept_id
order by od.ord_status
order by provinceName
order by cityName
order by countyName
order by town_name
order by m.device_code
desc
asc
) dt
dt.device_name like CONCAT('%', #{param.deviceName}, '%')

select * from ( SELECT DISTINCT m.iot_device_id, od.device_code as deviceCode, ( case when length(IFNULL(ten.device_name, '')) = 0 then m.device_name else ten.device_name end ) device_name, m.device_status, (CASE WHEN m.device_status = '0' THEN '在线' WHEN m.device_status = '1' THEN '离线' END) deviceStatusName, m.device_type as deviceType, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_model_type' AND DICT_VALUE = m.device_type limit 1) deviceTypeName, m.category_code, od.ord_status as orderStatus, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName, m.longitude, m.latitude, m.location, m.height, m.model_code, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'iot_device_mfgr_code' AND DICT_VALUE = m.model_code limit 1) modelName, od.tenant_id as tenantId, pro.area_name as provinceName, pro.area_code as province_id, city.area_name as cityName, city.area_code as city_id, county.area_name as countyName, county.area_code as county_id, town.area_code as town_code, town.area_name as town_name,
case when IFNULL(dct.user_device_coll_id,0) = 0 then '0' else '1' end isMonitor,
(CASE WHEN ( SELECT count(*) > 0 FROM vm_tenant_iot_device_conf_t ac WHERE ac.device_code = m.device_code AND ac.tenant_id = od.tenant_id ) THEN '1' ELSE '0' END) AS hasLinkConf FROM vm_order_sensor_devices od LEFT JOIN vm_order_customer oc on od.order_code = oc.order_code LEFT JOIN vm_iot_device_t m on m.device_code = od.device_code and m.category_code = 2 LEFT JOIN vm_tenant_iot_device_rel_t ten on ten.device_code = od.device_code and ten.tenant_id = od.tenant_id and ten.delete_flag='0' and ten.industry_code = od.industry_code LEFT JOIN sys_area pro on pro.area_code = m.province_id LEFT JOIN sys_area city on city.area_code = m.city_id LEFT JOIN sys_area county on county.area_code = m.county_id LEFT JOIN sys_area town on town.area_code = m.town_code
LEFT JOIN vm_organ_device_rel_t vod on vod.device_code = m.device_code and vod.delete_flag = '0' and vod.tenant_id = od.tenant_id
left join vm_user_device_collection_t dct on dct.coll_obj_code = m.device_code AND dct.coll_obj_type = '7' AND dct.user_id = #{param.userId}
where od.delete_flag = '0' and m.delete_flag = '0' and od.category_code = 2 and od.tenant_id =#{param.tenantId}
and vod.dept_id in
#{id}
AND m.province_id = #{param.provinceId}
AND m.city_id = #{param.cityId}
AND m.county_id = #{param.countyId}
AND m.town_code = #{param.townCode}
and m.device_code like CONCAT('%', #{param.deviceCode}, '%')
and m.device_status = #{param.deviceStatus}
and m.device_type = #{param.deviceType}
and m.device_type in
#{item}
and m.model_code = #{param.modelCode}
and od.ord_status in (0, 1, 2)
and od.ord_status = #{param.orderStatus}
AND exists not exists ( select 1 from vm_tenant_iot_device_conf_t ac where ac.device_code = m.device_code and ac.tenant_id = od.tenant_id )
${param.dataScope} GROUP BY od.tenant_id, od.industry_code, od.device_code
order by od.device_code
desc
asc
order by pro.area_code, city.area_code, county.area_code,od.device_code
) dt
dt.device_name like CONCAT('%', #{param.deviceName}, '%')
